 Class<?> cls=Class.forName("com.myproject.video.video_platform.controller.commerce."+args[0]);Path output=Path.of(args[1]);var builder=LauncherDiscoveryRequestBuilder.request();int selected=0;for(var method:cls.getDeclaredMethods())if(method.isAnnotationPresent(org.junit.jupiter.api.Test.class)&&(args.length==2||Arrays.asList(args).subList(2,args.length).contains(method.getName()))){builder.selectors(DiscoverySelectors.selectMethod(cls,method.getName()));selected++;}if(selected==0)throw new IllegalArgumentException("No declared catalog methods selected");
