@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"server.address=127.0.0.1","app.commerce.fake.auto-success=false","app.commerce.expiration-scan-ms=500"})
class CatalogScheduledAndEventTest extends CatalogPaymentStateTest {
 @Autowired TestRestTemplate http;@Autowired CommercePaymentEventService processor;@LocalServerPort int port;
 JsonNode actualRead(String c,UUID id)throws Exception{HttpHeaders headers=new HttpHeaders();headers.set("Cookie","JWT_TOKEN="+auth(buyer).getValue());ResponseEntity<CommerceOrderResponse> response=http.exchange("http://127.0.0.1:"+port+"/api/commerce/orders/"+id,HttpMethod.GET,new HttpEntity<>(headers),CommerceOrderResponse.class);Map<String,Object> observation=new LinkedHashMap<>();observation.put("case_id",c);observation.put("label","real-loopback-http-order-read");observation.put("actual_status",response.getStatusCode().value());observation.put("listener_address","127.0.0.1");observation.put("orders",orders.count());observation.put("attempts",attempts.count());observation.put("events",events.count());observation.put("entitlements",grants.count());observations.add(observation);assertEquals(HttpStatus.OK,response.getStatusCode());return mapper.valueToTree(response.getBody());}
 @Test void pay022ActualScheduledScanWithoutTriggeringRead()throws Exception{var past=paid();var success=paid();var future=paid();UUID pastId=orderId(checkout("PAY-022","overdue-fixture",buyer,List.of(past.getId()),"scan-past",201));UUID paidId=orderId(checkout("PAY-022","paid-control",buyer,List.of(success.getId()),"scan-paid",201));simulate("PAY-022",paidId,"PAID",200);UUID futureId=orderId(checkout("PAY-022","future-control",buyer,List.of(future.getId()),"scan-future",201));overdue(pastId);overdue(paidId);Instant deadline=Instant.now().plusSeconds(10);while(Instant.now().isBefore(deadline)&&orders.findById(pastId).orElseThrow().getStatus()!=CommerceOrderStatus.EXPIRED)Thread.sleep(100);assertEquals(CommerceOrderStatus.EXPIRED,orders.findById(pastId).orElseThrow().getStatus());assertEquals(PaymentAttemptStatus.EXPIRED,attempts.findByOrderId(pastId).orElseThrow().getStatus());assertEquals(CommerceOrderStatus.PAID,orders.findById(paidId).orElseThrow().getStatus());assertEquals(PaymentAttemptStatus.SUCCEEDED,attempts.findByOrderId(paidId).orElseThrow().getStatus());assertEquals(CommerceOrderStatus.PENDING,orders.findById(futureId).orElseThrow().getStatus());assertEquals(PaymentAttemptStatus.PENDING,attempts.findByOrderId(futureId).orElseThrow().getStatus());assertEquals(1,grants.count());assertEquals(1,events.count());observations.add(Map.of("case_id","PAY-022","label","scheduled-expiry-observed-before-any-order-GET","overdue_order_status","EXPIRED","overdue_attempt_status","EXPIRED","paid_control","PAID","future_control","PENDING","configured_scan_ms",500));assertEquals("EXPIRED",actualRead("PAY-022",pastId).path("status").asText());assertEquals("PAID",actualRead("PAY-022",paidId).path("status").asText());assertEquals("PENDING",actualRead("PAY-022",futureId).path("status").asText());}
 @Test void pay026DuplicateAndMismatchNormalizedSeam()throws Exception{var p=paid();UUID id=orderId(checkout("PAY-026","pending-seam-fixture",buyer,List.of(p.getId()),"event-seam",201));JsonNode initial=actualRead("PAY-026",id);for(NormalizedPaymentEvent event:List.of(new NormalizedPaymentEvent(PaymentProvider.FAKE,"wrong-amount",id,PaymentEventType.PAID,"qa-payment",1226,"EUR"),new NormalizedPaymentEvent(PaymentProvider.FAKE,"wrong-currency",id,PaymentEventType.PAID,"qa-payment",1225,"USD"),new NormalizedPaymentEvent(PaymentProvider.STRIPE,"wrong-provider",id,PaymentEventType.PAID,"qa-payment",1225,"EUR"))){CommerceException error=assertThrows(CommerceException.class,()->processor.process(event));assertEquals(HttpStatus.CONFLICT,error.getStatus());assertEquals(initial,actualRead("PAY-026",id));assertEquals(0,grants.count());assertEquals(0,events.count());observations.add(Map.of("case_id","PAY-026","label",event.providerEventId(),"seam_exception_status",error.getStatus().value(),"financial_snapshot_unchanged",true));}NormalizedPaymentEvent accepted=new NormalizedPaymentEvent(PaymentProvider.FAKE,"qa-exact-event",id,PaymentEventType.PAID,"qa-payment",1225,"EUR");processor.process(accepted);JsonNode paid=actualRead("PAY-026",id);assertEquals("PAID",paid.path("status").asText());assertEquals(1,grants.count());UUID grantId=grants.findAll().get(0).getId();assertEquals(1,events.count());processor.process(accepted);assertEquals(paid,actualRead("PAY-026",id));assertEquals(1,events.count());assertEquals(1,grants.count());assertEquals(grantId,grants.findAll().get(0).getId());assertEquals("SUCCEEDED",attempts.findByOrderId(id).orElseThrow().getStatus().name());access("PAY-026",p,true);assertEquals(Set.of(p.getId()),libraryIds("PAY-026"));NormalizedPaymentEvent refund=new NormalizedPaymentEvent(PaymentProvider.FAKE,"qa-refund-event",id,PaymentEventType.REFUNDED,null,1225,"EUR");processor.process(refund);JsonNode refunded=actualRead("PAY-026",id);processor.process(refund);assertEquals(refunded,actualRead("PAY-026",id));assertEquals(2,events.count());assertEquals(1,grants.count());assertEquals(grantId,grants.findAll().get(0).getId());access("PAY-026",p,false);assertEquals(0,library("PAY-026").size());}
}

